set statement_timeout='55s'; select string_agg(s,E'\n') s from (select concat_ws('|',e.vehicle_id,to_char(c.posted_at at time zone 'UTC','YYYY-MM-DD'),e.author_role,coalesce(e.polarity::text,'n'),count(*)) s from evidence_claims e join auction_comments c on c.id=e.source_comment_id where e.run_id in ('7e1d0c24-2026-4a10-9e00-0000000c2201','7e1d0c24-2026-4a10-9e00-0000000c2301') and e.status='active' and e.claim_kind='condition' and e.author_role in ('commenter','seller_comment') and coalesce(c.comment_type,'')<>'bid' and c.bid_amount is null and e.quote !~* '(\$\s?[0-9]|[0-9]+(\.[0-9])?\s?k\b|sold|hammer|final (bid|price)|winning|reserve)' and e.vehicle_id::text like '0%' group by e.vehicle_id,to_char(c.posted_at at time zone 'UTC','YYYY-MM-DD'),e.author_role,coalesce(e.polarity::text,'n')) q
